SELECT COUNT(*) AS "active_department_count"
FROM "departments"
WHERE "IsActive" = true LIMIT 100;

SELECT COUNT(*) AS "subcon_count"
FROM "participants"
WHERE "ParticipantType" = 'SUBCON' LIMIT 100;

SELECT COUNT(*) AS "visitor_participants_count"
FROM "participants"
WHERE "ParticipantType" = 'VISITOR' LIMIT 100;

SELECT AVG(sub.attempt_count)::numeric(10,2) AS avg_mcu_attempt_per_participant
FROM (
  SELECT COUNT(*) AS attempt_count
  FROM "mcu_results" mr
  WHERE mr."IsDeleted" = false
  GROUP BY mr."McuRegistrationId"
) reg_counts
JOIN LATERAL (
  SELECT reg_counts.attempt_count
) sub ON true LIMIT 100;

SELECT AVG(EXTRACT(EPOCH FROM (m."ScheduledDate" - m."RegistrationDate")) / 86400.0) AS "AvgGapDays" 
FROM "mcu_registrations" m
WHERE m."ScheduledDate" IS NOT NULL LIMIT 100;
